function hasTech(tech, names) {
  return tech.some((t) => names.includes(t));
}

async function main() {
  const categoryMap = {};
  for (const c of CATEGORIES) {
    const saved = await prisma.softwareCategory.upsert({ where: { slug: c.slug }, update: c, create: c });
    categoryMap[c.slug] = saved.id;
  }
  console.log(`categories: ${CATEGORIES.length}`);

  const developerMap = {};
  for (const d of DEVELOPERS) {
    const saved = await prisma.developer.upsert({ where: { slug: d.slug }, update: d, create: d });
    developerMap[d.slug] = saved.id;
  }
  console.log(`developers: ${DEVELOPERS.length}`);

  let created = 0;
  let updated = 0;
  for (const s of SOFTWARE) {
    const tech = s.tech || [];
    const data = {
      name: s.name,
      slug: s.slug,
      description: s.desc,
      developerId: developerMap[s.dev],
      categoryId: categoryMap[s.cat],
      licenseType: s.license,
      pricing: s.pricing,
      operatingSystems: s.os,
      technology: tech,
      version: s.version,
      officialWebsite: s.official,
      downloadUrl: s.download,
      documentationUrl: s.docs,
      tutorialUrl: s.tutorials,
      systemRequirements: s.reqs,
      keywords: s.keywords,
      hasGIS: hasTech(tech, ["GIS", "Web GIS"]),
      hasRemoteSensing: hasTech(tech, ["Remote Sensing", "Earth Observation"]),
      has3D: hasTech(tech, ["3D", "Visualization"]),
      hasCAD: tech.includes("CAD"),
      hasBIM: tech.includes("BIM"),
      hasWeb: hasTech(tech, ["Web GIS"]) || Boolean(s.web),
      hasDatabase: hasTech(tech, ["Database", "Spatial Data"]) || Boolean(s.db),
      hasPython: Boolean(s.py),
      studentAccess: Boolean(s.student),
      status: "PUBLISHED",
      verificationStatus: "UNKNOWN",
    };
    const existing = await prisma.software.findUnique({ where: { slug: s.slug } });
    if (existing) {
      const linksChanged = ["officialWebsite", "downloadUrl", "documentationUrl"].some((field) => existing[field] !== data[field]);
      await prisma.software.update({
        where: { slug: s.slug },
        data: {
          ...data,
          verificationStatus: linksChanged ? "UNKNOWN" : existing.verificationStatus,
          lastVerifiedAt: linksChanged ? null : existing.lastVerifiedAt,
        },
      });
      updated++;
    } else {
      await prisma.software.create({ data });
      created++;
    }
  }
  console.log(`software: ${created} created, ${updated} updated`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
